                    tp[0] = 0xE9;
                    const int32_t fwdDisp = static_cast<int32_t>(
                      reinterpret_cast<intptr_t>(tramp) -
                      static_cast<intptr_t>(target + 5));
                    std::memcpy(tp + 1, &fwdDisp, 4);
                    tp[5] = 0x90;
                    tp[6] = 0x90;
