                        reinterpret_cast<uintptr_t>(&g_b30_snap[i]);
                      const int32_t disp = static_cast<int32_t>(
                        static_cast<intptr_t>(snapAddr) -
                        static_cast<intptr_t>(reinterpret_cast<uintptr_t>(p + 4)));
                      std::memcpy(p, &disp, 4); p += 4;
