        //   F0 FF 04 88                        ; lock inc dword [rax+rcx*4]
        // skip:
        //   59                                 ; pop rcx
        //   58                                 ; pop rax
        //   48 8B C4                           ; mov rax, rsp        (replicate)
        //   48 89 58 08                        ; mov [rax+8], rbx   (replicate)
